<section class="card"><h2>Ordered rules</h2><?php if (!$rules): ?><div class="empty"><h3>No rules yet.</h3><p>Add a keyword above. Descriptions without a match stay uncategorized until you choose a category.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Priority</th><th>Keyword</th><th>Category</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($rules as $rule): ?><tr><td><?= e($rule['priority']) ?></td><td><strong><?= e($rule['keyword']) ?></strong></td><td><?= e($rule['category']) ?></td><td><?= $rule['enabled'] ? 'Enabled' : 'Paused' ?></td><td><div class="hero-actions"><a href="/salary/expense-rules?edit=<?= e($rule['id']) ?>">Edit</a><form method="post" action="/salary/expense-rules/<?= e($rule['id']) ?>/delete" data-confirm="Remove this category rule?"><?= csrf_field() ?><button class="quiet">Remove</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
